const MOD = 1_000_000_007n;

// Precompute factorials and inverse factorials for O(1) nCr queries
function precomputeFactorials(maxN) {
  const fact = new Array(maxN + 1);
  const invFact = new Array(maxN + 1);

  fact[0] = 1n;
  for (let i = 1; i <= maxN; i++) {
    fact[i] = fact[i - 1] * BigInt(i) % MOD;
  }

  invFact[maxN] = modPow(fact[maxN], MOD - 2n, MOD);
  for (let i = maxN - 1; i >= 0; i--) {
    invFact[i] = invFact[i + 1] * BigInt(i + 1) % MOD;
  }

  return { fact, invFact };
}

function nCr(n, k, fact, invFact) {
  if (k < 0 || k > n) return 0n;
  return fact[n] * invFact[k] % MOD * invFact[n - k] % MOD;
}

// Pascal's triangle for small n (up to ~1000)
function buildPascal(maxN) {
  const C = Array.from({ length: maxN + 1 }, () => new Array(maxN + 1).fill(0n));
  for (let i = 0; i <= maxN; i++) {
    C[i][0] = 1n;
    for (let j = 1; j <= i; j++) {
      C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD;
    }
  }
  return C;
}

function modPow(base, exp, mod) {
  let result = 1n;
  while (exp > 0n) {
    if (exp % 2n === 1n) result = result * base % mod;
    base = base * base % mod;
    exp = exp / 2n;
  }
  return result;
}
